package worker
import("context";"encoding/json";"errors";"testing")
func TestRegistryRegisterAndExecute(t *testing.T){r:=NewRegistry();called:=false;if err:=r.Register("test",func(ctx context.Context,p json.RawMessage)error{called=true;if string(p)!="{\"ok\":true}"{t.Fatalf("payload = %s",p)};return nil});err!=nil{t.Fatal(err)};if err:=r.Execute(context.Background(),"test",json.RawMessage("{\"ok\":true}"));err!=nil{t.Fatal(err)};if !called{t.Fatal("handler not called")};if err:=r.Register("test",func(context.Context,json.RawMessage)error{return nil});err==nil{t.Fatal("duplicate registration accepted")};if err:=r.Register("nil",nil);err==nil{t.Fatal("nil handler accepted")}}
func TestRegistryUnknownAndCancelled(t *testing.T){r:=DefaultRegistry();if err:=r.Execute(context.Background(),"missing",nil);err==nil{t.Fatal("unknown handler accepted")};ctx,cancel:=context.WithCancel(context.Background());cancel();if err:=r.Execute(ctx,"noop",json.RawMessage("{}"));!errors.Is(err,context.Canceled){t.Fatalf("error = %v",err)}}
